import{_ as i,o as n,c,a5 as o}from"./chunks/framework.CsGesDJn.js";const g=JSON.parse('{"title":"Task — G7 Subscription & Billing (Mobile, READ-ONLY)","description":"","frontmatter":{},"headers":[],"relativePath":"mobile/features/g7-subscription-billing/task.md","filePath":"mobile/features/g7-subscription-billing/task.md"}'),t={name:"mobile/features/g7-subscription-billing/task.md"};function a(l,e,r,h,s,d){return n(),c("div",null,[...e[0]||(e[0]=[o('<h1 id="task-—-g7-subscription-billing-mobile-read-only" tabindex="-1">Task — G7 Subscription &amp; Billing (Mobile, READ-ONLY) <a class="header-anchor" href="#task-—-g7-subscription-billing-mobile-read-only" aria-label="Permalink to &quot;Task — G7 Subscription &amp; Billing (Mobile, READ-ONLY)&quot;">​</a></h1><p>&gt; <a href="./spec.html">spec.md</a></p><h2 id="chan-truoc-khi-code-can-xac-nhan-voi-be-pm" tabindex="-1">Chặn trước khi code (cần xác nhận với BE/PM) <a class="header-anchor" href="#chan-truoc-khi-code-can-xac-nhan-voi-be-pm" aria-label="Permalink to &quot;Chặn trước khi code (cần xác nhận với BE/PM)&quot;">​</a></h2><ul><li>[ ] <strong>Hỏi BE route plan nào là chính thức</strong> — hệ cũ <code>SubscriptionController</code> (User-scoped) vs hệ mới <code>BillingPlanController</code>/<code>BillingController</code> (Agency-scoped). Spec đề xuất ưu tiên hệ mới nhưng chưa confirm (mục 8 câu 2).</li><li>[ ] <strong>Hỏi BE route invoice nào chính thức</strong> — <code>/billing/transactions</code> vs <code>/billing/agencies/{agencyId}/invoices</code> có vẻ trùng chức năng (mục 8 câu 3).</li><li>[ ] <strong>Xác nhận với PM</strong>: khuyến nghị &quot;không thanh toán thật trong app, chỉ mở web ngoài&quot; ở spec mục 7 là đề xuất của tài liệu, <strong>chưa phải quyết định đã chốt</strong> — cần duyệt trước khi lên implementation plan thật.</li><li>[ ] Tra seed data (<code>AdminDemoSeeder.java</code>) hoặc DB nếu cần số liệu thật (giá/credit mỗi plan) để demo UI.</li></ul><h2 id="current-plan-screen" tabindex="-1">Current Plan screen <a class="header-anchor" href="#current-plan-screen" aria-label="Permalink to &quot;Current Plan screen&quot;">​</a></h2><ul><li>[ ] <code>GET /billing/agencies/{agencyId}/subscription</code> (hoặc <code>/subscription/me</code> nếu BE xác nhận dùng hệ cũ) — hiển thị plan name, trạng thái, <code>currentPeriodEnd</code>.</li><li>[ ] Block AI credit allowance — <code>GET /billing/credits/{agencyId}/usage?month=&lt;tháng hiện tại&gt;</code>, hiển thị <code>allowance/used/remaining/creatorLimit/creatorUsed</code>.</li></ul><h2 id="plan-comparison-list" tabindex="-1">Plan comparison list <a class="header-anchor" href="#plan-comparison-list" aria-label="Permalink to &quot;Plan comparison list&quot;">​</a></h2><ul><li>[ ] <code>GET /billing/plans</code> — card mỗi plan: <code>displayName, priceMonthly, monthlyAiCredits, maxActiveWorkspaces, maxInternalMembers, isSellable, checkoutEnabled</code>.</li><li>[ ] Nút &quot;Nâng cấp&quot; — <strong>KHÔNG mở checkout trong app</strong>, dùng <code>Linking.openURL()</code> mở trình duyệt ngoài tới <code>/subscription/checkout?tier=...</code> của web (không WebView nhúng).</li></ul><h2 id="invoice-history" tabindex="-1">Invoice history <a class="header-anchor" href="#invoice-history" aria-label="Permalink to &quot;Invoice history&quot;">​</a></h2><ul><li>[ ] <code>GET /invoices?cursor&amp;limit&amp;status&amp;kind&amp;from&amp;to</code> — <code>useInfiniteQuery</code> theo <code>cursor</code>/<code>nextCursor</code> (không dùng offset).</li><li>[ ] List hiển thị <code>planCode, amount, currency, status, createdAt, paidAt</code> + filter status/kind/khoảng ngày.</li><li>[ ] Invoice Detail — <code>GET /invoices/{orderId}</code>, hiển thị <code>productSnapshot</code>, <code>payments</code> (verificationState từng payment), <code>reviewReasons</code> nếu có.</li><li>[ ] Nút &quot;Tải receipt&quot; — <code>GET /invoices/{orderId}/receipt</code> (file <code>.txt</code>, không JSON) — dùng Expo file system API, không cache (luôn fetch mới).</li></ul><h2 id="state-cache" tabindex="-1">State/cache <a class="header-anchor" href="#state-cache" aria-label="Permalink to &quot;State/cache&quot;">​</a></h2><ul><li>[ ] <code>[&#39;billing&#39;,&#39;agency&#39;,agencyId,&#39;subscription&#39;]</code> — staleTime ngắn (vài phút, đổi qua webhook SePay).</li><li>[ ] <code>[&#39;billing&#39;,&#39;plans&#39;]</code> — cache lâu (<code>staleTime: 1 hour</code>).</li><li>[ ] <code>[&#39;billing&#39;,&#39;agency&#39;,agencyId,&#39;credits&#39;,month]</code> — key theo <code>month</code> tránh lẫn dữ liệu tháng cũ.</li><li>[ ] <code>[&#39;billing&#39;,&#39;agency&#39;,agencyId,&#39;invoices&#39;,filters]</code> — infinite query.</li></ul><h2 id="business-rules-can-hien-thi-đung" tabindex="-1">Business rules cần hiển thị đúng <a class="header-anchor" href="#business-rules-can-hien-thi-đung" aria-label="Permalink to &quot;Business rules cần hiển thị đúng&quot;">​</a></h2><ul><li>[ ] AI credit 2 lớp: hạn mức Agency (plan) + hạn mức Creator (Owner set) — <code>remaining = min(agency_remaining, creator_limit - creator_used)</code> nếu có set riêng.</li><li>[ ] Hạn mức Creator là hard limit — hết credit chặn hẳn thao tác AI, không phải soft warning.</li><li>[ ] Credit Plan không rollover sang kỳ sau; dùng credit Plan trước, credit mua thêm sau (không hết hạn).</li><li>[ ] Subscription hết hạn vẫn reset hạn mức hàng tháng theo anchor cũ.</li><li>[ ] Payment gateway thật là <strong>SePay</strong> (QR chuyển khoản), KHÔNG phải PayOS như BA doc ghi — không hiển thị nhầm tên gateway trong UI (mục 8 câu 1).</li></ul><h2 id="co-the-lam-them-neu-con-thoi-gian-rui-ro-thap-khong-phai-tien" tabindex="-1">Có thể làm thêm nếu còn thời gian (rủi ro thấp, không phải tiền) <a class="header-anchor" href="#co-the-lam-them-neu-con-thoi-gian-rui-ro-thap-khong-phai-tien" aria-label="Permalink to &quot;Có thể làm thêm nếu còn thời gian (rủi ro thấp, không phải tiền)&quot;">​</a></h2><ul><li>[ ] <code>PUT /billing/credits/{agencyId}/limits</code> (Set Credit, FR 3.9.7) — Owner-only, chỉ ghi số nguyên hạn mức.</li></ul><h2 id="chua-lam-out-of-scope-g7-xem-spec-muc-7" tabindex="-1">Chưa làm / out of scope G7 (xem spec mục 7) <a class="header-anchor" href="#chua-lam-out-of-scope-g7-xem-spec-muc-7" aria-label="Permalink to &quot;Chưa làm / out of scope G7 (xem spec mục 7)&quot;">​</a></h2><ul><li>[ ] Không làm: <code>POST /subscription</code>, <code>POST /billing/agencies/{agencyId}/orders</code>, <code>POST /billing/credits/buy</code>, <code>POST /subscription/cancel</code>, hiển thị QR SePay trong app — mọi hành động mua/upgrade/thanh toán chỉ mở web ngoài.</li></ul><h2 id="rui-ro-can-chot-truoc-khi-code-xem-spec-muc-8" tabindex="-1">Rủi ro cần chốt trước khi code (xem spec mục 8) <a class="header-anchor" href="#rui-ro-can-chot-truoc-khi-code-xem-spec-muc-8" aria-label="Permalink to &quot;Rủi ro cần chốt trước khi code (xem spec mục 8)&quot;">​</a></h2><ol><li>BA doc ghi payment gateway PayOS nhưng code dùng SePay — cần BA/PM xác nhận doc chưa update hay đổi gateway giữa đường.</li><li>2 hệ plan song song (User-scoped cũ vs Agency-scoped mới) — xác nhận route nào web đang dùng thật trước khi mobile tích hợp.</li><li><code>/billing/transactions</code> vs <code>/billing/agencies/{id}/invoices</code> trùng chức năng — xác nhận route active, tránh build trên route deprecated.</li><li>Khuyến nghị &quot;mở web ngoài&quot; là đề xuất riêng của spec, chưa phải quyết định chính thức.</li><li>Số liệu giá/credit mỗi plan nằm trong seed/migration, không đọc được trực tiếp từ code Java.</li></ol>',20)])])}const m=i(t,[["render",a]]);export{g as __pageData,m as default};
